// Kitchen plan lanes: runs on records.onDataQuerySuccess and the Kitchen plan page's onPageLoad
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const d = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? new Date(s + 'T12:00:00Z').toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : 'Unscheduled';
const active = (queries.records.data || []).filter(r => !['Completed', 'Cancelled'].includes(r.status));
const stages = ['Draft', 'Scheduled', 'In progress', 'Ready'];
const colors = ['var(--cc-primary-brand)', '#7c6aa8', '#b77b3c', '#43826f'];
return {
  activeCount: active.length,
  lanes: stages.map((stage, i) => {
    const inLane = active.filter(r => r.status === stage);
    const [a, b] = inLane;
    return {
      stage, color: colors[i], count: inLane.length,
      c1name: a ? e(a.name) : '', c1meta: a ? e(a.owner) + ' · ' + d(a.due) : '',
      c2name: b ? e(b.name) : '', c2meta: b ? e(b.owner) + ' · ' + d(b.due) : ''
    };
  })
};

// Selected order for the Order production page: runs on records.onDataQuerySuccess and the page's onPageLoad
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const p = (queries.records.data || []).find(r => r.id === variables.recordId);
const money = n => Number(n || 0).toLocaleString('en-US', {style: 'currency', currency: 'USD'});
const date = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? new Date(s + 'T12:00:00Z').toLocaleDateString('en-GB', {day: '2-digit', month: 'short', year: 'numeric'}) : 'Not scheduled';
const time = n => String(Math.floor(n)).padStart(2, '0') + ':' + String(Math.round((n % 1) * 60)).padStart(2, '0');
const total = Math.round((p?.items || []).reduce((n, i) => n + Number(i.quantity || 0) * Number(i.rate || 0), 0) * 100) / 100;
const paid = Math.round((p?.decisions || []).filter(d => d.type === 'payment').reduce((n, d) => n + Number(d.amount || 0), 0) * 100) / 100;
const b = (p?.decisions || []).filter(d => d.type === 'booking').at(-1);
const history = (p?.history || []).slice().reverse().map(h => ({ event: e(h.event), at: e(String(h.at || '').slice(0, 16).replace('T', ' ')), note: h.note || '' }));
return {
  has: !!p,
  client: p?.context || 'Choose a record',
  scope: p?.scope || 'Open a ticket from the register.',
  owner: p?.owner || 'Unassigned',
  booking: b ? date(b.date) + ' · ' + time(b.start) + '–' + time(b.start + b.duration) : 'Schedule after customer approval',
  status: p?.status || 'Not selected',
  total: money(total),
  remaining: money(total - paid) + ' remaining',
  history: history.length ? history : [{ event: '', at: 'Select a record to inspect its saved activity.', note: '' }]
};
